mapper.select:
SELECT * FROM likes
WHERE user_id = #{userId, typeHandler=com.flittly.bankendspringboot.config.UUIDTypeHandler}
  AND target_id = #{targetId, typeHandler=com.flittly.bankendspringboot.config.UUIDTypeHandler}
  AND target_type = #{targetType, typeHandler=org.apache.ibatis.type.EnumTypeHandler}

mapper.delete:
DELETE FROM likes
WHERE user_id = #{userId, typeHandler=com.flittly.bankendspringboot.config.UUIDTypeHandler}
  AND target_id = #{targetId, typeHandler=com.flittly.bankendspringboot.config.UUIDTypeHandler}
  AND target_type = #{targetType, typeHandler=org.apache.ibatis.type.EnumTypeHandler}
